<script setup lang="ts">
import {onBeforeUnmount,onMounted,ref,watch} from 'vue';import L from 'leaflet';import type {Vehicle} from '../types';
const props=defineProps<{active:boolean}>();const target=ref<HTMLElement>();const failed=ref(false);const stale=ref(false);let map:L.Map|undefined;let source:EventSource|undefined;let timer:number|undefined;let markers:L.CircleMarker[]=[];
const route:[number,number][]=[[-6.0639,-49.9304],[-6.0648,-49.9265],[-6.0698,-49.9101],[-6.077,-49.8758],[-6.08,-49.868],[-6.083,-49.861],[-6.09164,-49.85605]];
function renderVehicles(list:Vehicle[]){markers.forEach(m=>m.remove());markers=list.map(v=>L.circleMarker([v.latitude,v.longitude],{radius:7,color:'#fff',weight:2,fillColor:v.line==='TA275'?'#687f52':'#397d8c',fillOpacity:1}).bindTooltip(`${v.vehicleId} · ${v.line}<br>Próxima: ${v.nextStop} · ${v.etaMinutes} min (simulado)`).addTo(map!));stale.value=false;window.clearTimeout(timer);timer=window.setTimeout(()=>stale.value=true,12000)}
async function poll(){try{const r=await fetch('/api/simulation/vehicles');if(r.ok)renderVehicles(await r.json())}catch{stale.value=true}}
onMounted(()=>{try{map=L.map(target.value!,{zoomControl:true}).setView([-6.078,-49.892],13);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'&copy; OpenStreetMap',maxZoom:19}).on('tileerror',()=>failed.value=true).addTo(map);L.polyline(route.slice(0,2),{color:'#397d8c',weight:5,dashArray:'2 9',lineCap:'round'}).bindTooltip('Caminhada inicial aproximada').addTo(map);L.polyline(route.slice(1,4),{color:'#176a9b',weight:6}).bindTooltip('D01 demonstrativa').addTo(map);L.polyline(route.slice(3,6),{color:'#537a3b',weight:6}).bindTooltip('TA275 demonstrativa').addTo(map);L.polyline(route.slice(5),{color:'#397d8c',weight:5,dashArray:'2 9',lineCap:'round'}).bindTooltip('Caminhada final aproximada').addTo(map);L.circleMarker(route[0],{radius:8,color:'#173d32',fillColor:'#f3ebdd',fillOpacity:1}).bindTooltip('Tropical').addTo(map);L.circleMarker(route[3],{radius:9,color:'#173d32',fillColor:'#f3ebdd',fillOpacity:1}).bindTooltip('Baldeação · Parada Amazônica',{permanent:true,direction:'top'}).addTo(map);L.circleMarker(route[6],{radius:8,color:'#b94724',fillColor:'#f3ebdd',fillOpacity:1}).bindTooltip('Partage Shopping').addTo(map);source=new EventSource('/api/simulation/stream');source.addEventListener('vehicles',e=>renderVehicles(JSON.parse((e as MessageEvent).data)));source.onerror=()=>{source?.close();stale.value=true;poll();window.setInterval(poll,10000)}}catch{failed.value=true}});watch(()=>props.active,()=>setTimeout(()=>map?.invalidateSize(),100));onBeforeUnmount(()=>{source?.close();window.clearTimeout(timer);map?.remove()});
</script>
<template><section class="map-shell" aria-labelledby="map-title"><div class="map-toolbar"><div><h2 id="map-title">Mapa do trajeto</h2><p>Selecione um veículo para ver próxima parada e ETA simulado.</p></div><span v-if="stale" class="status stale">Posição desatualizada</span><span v-else class="status">Simulação ativa</span></div><div ref="target" class="map" :class="{hidden:failed}" aria-label="Mapa com caminhada aproximada, D01, baldeação e TA275 demonstrativas entre Tropical e Partage Shopping"></div><div v-if="!failed" class="map-legend" aria-label="Legenda do trajeto"><span><i class="d01"></i>D01 sintética</span><span><i class="ta275"></i>TA275 sintética</span><span><i class="walking"></i>Caminhada aproximada</span></div><div v-if="failed" class="map-fallback"><strong>Camada cartográfica indisponível</strong><p>O trajeto continua acessível na lista de etapas abaixo.</p></div></section></template>
